console.log(`Starting Part 5 enrichment (Collection size: ${VOCAB_PART_5.length})...`);
let added = 0;
let skipped = 0;

for (const [word, pos, def, examples, variations] of VOCAB_PART_5) {
  const cleanWord = word.trim().toLowerCase();
  if (dictionaryManager.hasWord(cleanWord)) {
    skipped++;
    continue;
  }

  const res = dictionaryManager.addWord({
    word: cleanWord,
    meanings: [{
      partOfSpeech: pos,
      definition: def,
      examples: Array.isArray(examples) ? examples : []
    }],
    variations: Array.isArray(variations) ? variations : []
  }, false);

  if (res.added) {
    added++;
  }
}

const stats = dictionaryManager.getStats();
console.log(`Part 5 completed!`);
console.log(`Newly added: ${added}`);
console.log(`Already existed: ${skipped}`);
console.log(`Total words in dictionary now: ${stats.totalWords}`);
console.log(`Per-letter breakdown:`, JSON.stringify(stats.letterCounts, null, 2));
